#!/usr/bin/env python3
"""Build the BRYME 500-title catalogue batch.
Only real, famous titles with verified basic facts (year, country, genre, premise).
Trailers: only verified official IDs are included; everything else stays empty
so the site shows the clean 'Trailer unavailable' state."""
import json, os, re, urllib.request

def verify(vid):
    url = f"https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={vid}&format=json"
    try:
        with urllib.request.urlopen(url, timeout=8) as r:
            return json.loads(r.read().decode())
    except Exception:
        return None

def norm(s): return re.sub(r'[^a-z0-9]+',' ',s.lower()).strip()

# (id, title, year, genre, country, synopsis, youtubeId_or_None)
# GENRES allowed by the site: Drama, Action, Superhero, Sci-Fi, Horror, Thriller,
# Series, Animation, Anime, Comedy, Crime, Fantasy, War, Romance, Korean
T = []
def add(id, title, year, genre, country, syn, yt=None):
    T.append(dict(id=id, title=title, slug=id, description=syn, year=year,
                  genre=genre, country=country, language="English", status="published",
                  youtubeId=yt, trailer=f"https://www.youtube.com/watch?v={yt}" if yt else None,
                  poster=f"https://i.ytimg.com/vi/{yt}/hqdefault.jpg" if yt else None))

